const DICTS: Record<Exclude<Lang, 'en'>, Record<string, string>> = { tr: TR, de: DE }
const isLang = (v: unknown): v is Lang => LANGS.some((l) => l.code === v)

const LangContext = createContext<{ lang: Lang; setLang: (l: Lang) => void }>({ lang: 'en', setLang: () => {} })

function initial(): Lang {
  try {
    const saved = localStorage.getItem(KEY)
    if (isLang(saved)) return saved
  } catch {
    // storage unavailable
  }
  const browser = typeof navigator !== 'undefined' ? navigator.language?.slice(0, 2).toLowerCase() : ''
  return isLang(browser) ? browser : 'en'
}

export function LangProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(initial)
  useEffect(() => {
    document.documentElement.lang = lang
  }, [lang])
  const setLang = useCallback((l: Lang) => {
    setLangState(l)
    try {
      localStorage.setItem(KEY, l)
    } catch {
      // storage unavailable
    }
  }, [])
  return <LangContext value={{ lang, setLang }}>{children}</LangContext>
}

/** Number ranges such as 2021-2026 or 1-4 never break at the hyphen: invisible word joiners (U+2060) keep them whole. */
const WORD_JOINER = String.fromCharCode(0x2060)
const keepRanges = (s: string) => s.replace(/([0-9])-([0-9])/g, `$1${WORD_JOINER}-${WORD_JOINER}$2`)

/** `t('English text')` returns the translation for the active language, falling back to the English text. */
/** Puts values into a translated sentence: fill(t('Below {limit} the plot fails.'), { limit: '15%' }).
 *  Each language places the {placeholders} where its grammar needs them. */
export const fill = (s: string, v: Record<string, unknown>) => s.replace(/\{(\w+)\}/g, (_, k: string) => String(v[k]))

export function useT() {
  const { lang, setLang } = useContext(LangContext)
  const t = useCallback((s: string) => keepRanges(lang === 'en' ? s : (DICTS[lang][s] ?? s)), [lang])
  return { t, lang, setLang }
}
